<template><view class="page"><view class="head"><view class="eyebrow">未来任务配置</view><view class="title">检查表模板</view><view class="copy">更新模板只影响后续周期；历史履职记录保留原始版本。</view></view><view v-if="!allowed" class="denied">无模板管理权限</view><template v-else><view v-for="item in templates" :key="item.name" class="row"><view><view class="name">{{item.name}}</view><view class="copy">{{item.category}} · {{item.frequency}} · 适用 {{item.target}}</view></view><view class="state" :class="{off:!item.enabled}">{{item.enabled?'启用':'停用'}}</view></view><view class="reserved"><view class="name">送气工画像接口预留</view><view class="copy">已预留关码次数、严重度、A/B/C 分级、60 天滚动降级与网格长字段；首版不开放页面。</view></view></template></view></template>
<script setup>import {computed} from 'vue';import {demoStore} from '../../stores/demo';const allowed=computed(()=>demoStore.can('admin'));const templates=[{name:'每周安全检查',category:'安全检查',frequency:'每周',target:'全员',enabled:true},{name:'每月线下抽查',category:'线下抽查',frequency:'每月',target:'安监部',enabled:true},{name:'季度安全宣教',category:'安全宣教',frequency:'每季度',target:'各部门',enabled:false}]</script>
<style lang="scss" scoped>.page{padding:32rpx 28rpx;max-width:1040px;margin:auto}.eyebrow{font-size:20rpx;letter-spacing:3rpx;color:#9f2349}.title{font-size:43rpx;font-weight:750;margin:5rpx 0}.copy{font-size:22rpx;color:#756c6b;line-height:1.6}.row{background:#fffcfa;border-radius:17rpx;padding:23rpx;display:flex;align-items:center;justify-content:space-between;margin-top:14rpx}.name{font-size:28rpx;font-weight:680;margin-bottom:4rpx}.state{font-size:21rpx;background:#edf5ef;color:#287144;padding:7rpx 11rpx;border-radius:8rpx}.state.off{background:#eee8e5;color:#756c6b}.reserved{margin-top:24rpx;padding:24rpx;background:#fff8f8;border-left:6rpx solid #9f2349}.denied{text-align:center;padding:100rpx;color:#756c6b}@media(min-width:900px){.page{padding:28px 30px}.eyebrow{font-size:11px}.title{font-size:29px}.copy{font-size:13px}.row{border-radius:15px;padding:19px;margin-top:12px}.name{font-size:17px}.state{font-size:12px}.reserved{margin-top:20px;padding:20px}}</style>
